import math

def sigma(n):
    """Calculates the sum of divisors of n."""
    s = 1
    temp = n
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            p = i
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            # Sum of divisors formula for p^count: (p^(count+1) - 1) / (p - 1)
            s *= (p**(count + 1) - 1) // (p - 1)
        i += 1
    if temp > 1:
        # Remaining temp is a prime factor
        s *= (temp + 1)
    return s

def tau(n):
    """Calculates the number of divisors of n."""
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

