def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # Optimization: The total sum must be a perfect square
    total_sum = sum(divisors)
    if not is_perfect_square(total_sum):
        return False

    # Backtracking search function
    # We use a state based approach to avoid generating all n! permutations unnecessarily

    def solve(current_path, remaining_divisors, current_sum):
        if len(current_path) == n:
            # The sum is already checked at the previous step, but confirm for safety
            return is_perfect_square(current_sum)

        # Iterate over available divisors to try the next step
        for i in range(len(remaining_divisors)):
            d = remaining_divisors[i]
            new_sum = current_sum + d

            if is_perfect_square(new_sum):
                # Prepare for recursion
                new_path = current_path + [d]
                # Create the new list of remaining divisors efficiently
                new_remaining = remaining_divisors[:i] + remaining_divisors[i+1:]

                # Recurse
                if solve(new_path, new_remaining, new_sum):
                    return True
        return False

    # Start the search. The first element a1 must be a perfect square.
    # Since a1 is a divisor, and divisors are positive integers, a1 must be a perfect square itself.
    for d1 in divisors:
        if is_perfect_square(d1):
            remaining = divisors[:divisors.index(d1)] + divisors[divisors.index(d1)+1:]
            if solve([d1], remaining, d1):
                return True

    return False

